export const HOWTO = {
flat_db_press:{s:["Sit on a flat bench, a dumbbell resting on each thigh.","Lie back, using your knees to kick the bells up to shoulder height.","Press straight up until your arms lock over your chest.","Lower until your elbows drop just past your torso."],w:"Keep elbows about 45° from your ribs. Flaring them to 90° is what wrecks shoulders."},
incline_db_press:{s:["Set the bench to 30-45°.","Lie back with the bells at shoulder height, palms forward.","Press up and slightly back, over your collarbone.","Lower under control until you feel the stretch across your upper chest."],w:"Past 45° the move becomes a shoulder press and your chest stops working."},
squeeze_press:{s:["Lie on a flat bench holding two bells together over your chest, palms facing each other.","Press them into each other hard and keep that pressure the whole set.","Lower to your chest, still squeezing.","Press back up."],w:"The squeeze is the exercise. If the bells drift apart, you are just doing a press."},
pushup_burnout:{s:["Hands under your shoulders, body in one straight line.","Lower until your chest is a fist off the floor.","Push back up, locking out.","Go until your form breaks, not until it hurts."],w:"Hips sagging or piking means the set is over."},
feet_elev_pushup:{s:["Put your feet on a bench, hands on the floor under your shoulders.","Keep a straight line from heels to head.","Lower your chest to the floor.","Press back up."],w:"Higher feet means more load on the upper chest and shoulders. Don't let the hips drop."},
diamond_pushup:{s:["Hands together under your chest, index fingers and thumbs forming a triangle.","Keep elbows tucked close to your ribs.","Lower your chest to your hands.","Press up."],w:"Elbows flaring out turns this back into a normal push-up and drops the triceps out of it."},
close_grip_press:{s:["Lie on a flat bench, EZ bar with hands about shoulder-width on the inner grips.","Press the bar over your lower chest.","Lower with elbows tucked tight to your sides.","Press back up."],w:"Grip narrower than shoulder-width strains the wrists without adding tricep work."},
db_fly:{s:["Lie flat, bells above your chest, palms facing each other.","Keep a soft, fixed bend in the elbows.","Open your arms wide until you feel a stretch across the chest.","Bring them back together over your chest."],w:"The elbow angle never changes. If it bends and straightens, you are pressing."},
incline_db_fly:{s:["Set the bench to 30°.","Start with the bells above your chest, palms facing each other, elbows softly bent.","Open wide until you feel the stretch.","Hug them back together."],w:"Go lighter than feels right. Flyes are a stretch exercise, not a strength one."},
cable_crossover:{s:["Set both pulleys low.","Grab a handle in each hand, step forward into a split stance.","Sweep your hands up and together in front of your chest.","Hold the squeeze for a beat, then lower with control."],w:"Drive with the chest, not the front delts. Hands finish in front of your sternum, not your chin."},
db_pullover:{s:["Lie flat on a bench holding one dumbbell over your chest with both hands under the top plate.","Keep elbows slightly bent.","Lower the bell back over your head until you feel the stretch through your lats.","Pull it back over your chest."],w:"Ribs stay down. Arching your lower back to get more range just loads your spine."},
pullup:{s:["Hang from the bar, palms forward, hands just outside shoulder-width.","Pull your shoulder blades down before your arms bend.","Pull until your chin clears the bar.","Lower all the way to straight arms."],w:"Use the assist machine or a band rather than kipping. Half-reps don't build the back."},
chinup:{s:["Hang with palms facing you, hands shoulder-width.","Pull your elbows down toward your ribs.","Bring your chin over the bar.","Lower under control to a full hang."],w:"Underhand grip pulls the biceps in hard, so expect more reps here than on pull-ups."},
wide_pullup:{s:["Grip well outside shoulder-width, palms forward.","Pull the chest toward the bar, elbows tracking out and down.","Clear the bar with your chin.","Lower to a full hang."],w:"Expect fewer reps than a normal pull-up. Don't chase the same number."},
lat_pulldown:{s:["Set the thigh pad snug so you don't lift off the seat.","Grip wide, palms forward.","Pull the bar to your upper chest, leading with the elbows.","Let it rise back to a full stretch."],w:"Pull to the chest, never behind the neck. Lean back no more than about 15°."},
cs_db_row:{s:["Set an incline bench to about 30° and lie chest-down on it.","Let the bells hang straight down.","Row them to your hips, squeezing the shoulder blades.","Lower to a full stretch."],w:"The bench does the cheating for you. If your chest comes off it, the weight is too heavy."},
single_arm_row:{s:["Put one knee and the same-side hand on a bench.","Let the dumbbell hang from your free hand.","Row it to your hip, elbow tracking past your ribs.","Lower to a full stretch."],w:"Don't rotate your torso to lift the bell. Shoulders stay square to the floor."},
seated_row:{s:["Sit with feet braced, knees slightly bent.","Grab the handle, sit tall with chest up.","Pull to your stomach, driving the elbows straight back.","Let it return until your shoulder blades spread."],w:"Your torso stays upright. Rocking back and forth is your lower back doing the lifting."},
renegade_row:{s:["Get into a push-up position gripping a dumbbell in each hand, feet wide.","Row one bell to your hip while the other braces on the floor.","Lower it under control.","Alternate sides."],w:"Hips must not rotate. If they twist, widen your feet or drop the weight."},
inverted_row:{s:["Set a Smith bar or rack bar at about hip height.","Hang underneath it, body straight, heels on the floor.","Pull your chest to the bar.","Lower to straight arms."],w:"Make it harder by walking your feet out, easier by raising the bar."},
back_extension:{s:["Set the pads of a 45-degree back extension bench just below your hip bones, heels locked in.","Hold one dumbbell against your chest with both arms crossed over it.","Hinge at the hips and lower your torso until it is just past straight down, back flat.","Squeeze your glutes and hamstrings to raise back to a straight line."],w:"Stop at a straight line. Arching past it turns a hinge into a lower-back crunch."},
db_shrug:{s:["Stand holding a heavy dumbbell in each hand at your sides.","Shrug straight up toward your ears.","Hold at the top for a full second.","Lower all the way down."],w:"Don't roll your shoulders. Straight up and straight down."},
goblet_squat:{s:["Hold one dumbbell vertically against your chest, both hands under the top plate.","Feet shoulder-width, toes turned slightly out.","Sit down between your heels, keeping your chest tall.","Drive up through mid-foot."],w:"Elbows should brush the inside of your knees at the bottom. If they don't, you aren't deep enough."},
bulgarian:{s:["Stand a stride in front of a bench, dumbbell in each hand.","Rest the top of your back foot on the bench.","Drop straight down until your front thigh is parallel.","Drive up through the front heel."],w:"Keep your weight on the front leg. The back leg is a kickstand, not a pusher."},
walking_lunge:{s:["Stand tall with a dumbbell in each hand.","Step forward and drop your back knee toward the floor.","Push through the front heel to stand.","Step through into the next rep with the other leg."],w:"Front knee tracks over the middle toes. Take a longer step to hit glutes, shorter for quads."},
db_front_squat:{s:["Clean two dumbbells to your shoulders, elbows high, palms facing in.","Feet shoulder-width.","Squat down, keeping your torso upright.","Drive up through your heels."],w:"Elbows dropping pitches you forward. Keep them pointed ahead the whole set."},
db_step_up:{s:["Stand facing a bench or box at about knee height, dumbbell in each hand.","Plant one whole foot on the box.","Drive through that heel to stand fully upright.","Lower under control, don't drop."],w:"Do not push off the bottom foot. All the work comes from the leg on the box."},
reverse_lunge:{s:["Stand tall, dumbbell in each hand.","Step backward and drop the back knee toward the floor.","Keep your weight on the front foot.","Push through the front heel to return."],w:"Easier on the knees than a forward lunge. Step straight back, not out to the side."},
sumo_squat:{s:["Hold one heavy dumbbell hanging between your legs with both hands.","Stand wide, toes turned out about 45°.","Squat straight down, knees tracking over your toes.","Drive up, squeezing the glutes at the top."],w:"Knees caving inward is the whole failure mode. Push them out."},
lateral_lunge:{s:["Stand tall with a dumbbell in each hand, feet together.","Step wide to one side and sit back into that hip.","Keep the trailing leg straight.","Push off the bent leg to return to center."],w:"Both feet stay flat and pointed forward. Sit back into the hip, don't just bend the knee."},
db_rdl:{s:["Stand holding a dumbbell in front of each thigh.","Push your hips back, letting the bells slide down your legs.","Stop when you feel a strong hamstring stretch, around mid-shin.","Drive your hips forward to stand."],w:"Legs stay nearly straight with a soft knee. This is a hip hinge, not a squat."},
single_leg_rdl:{s:["Hold one dumbbell in the hand opposite your standing leg.","Hinge at the hip, letting the free leg swing straight back as a counterweight.","Lower until your torso is near parallel to the floor.","Squeeze the glute to stand."],w:"Hips stay level. If the free-leg hip opens toward the ceiling, you've rotated."},
db_good_morning:{s:["Hold one dumbbell against your upper chest with both hands.","Feet hip-width, soft knees.","Hinge at the hips and lower your torso toward parallel.","Squeeze the glutes to stand tall."],w:"Go light. Your back stays flat the entire time. Round it and you're loading your spine."},
stiff_leg_dl:{s:["Stand holding a dumbbell in front of each thigh, legs nearly straight.","Hinge at the hips and lower the bells down the front of your legs.","Go to the deepest point you can hold a flat back.","Drive the hips forward to stand."],w:"Straighter legs than an RDL, so use less weight and expect more hamstring stretch."},
glute_bridge:{s:["Lie on your back, knees bent, feet flat and close to your butt.","Rest a dumbbell across your hips, held with both hands.","Drive through your heels and lift your hips until your body is a straight line.","Squeeze hard at the top for a second, then lower."],w:"Ribs down and chin tucked. Arching your lower back is not the same as extending your hips."},
hip_thrust:{s:["Sit on the floor with your upper back against a bench, dumbbell across your hips.","Feet flat, shins vertical at the top of the rep.","Drive through your heels until hips are level with knees.","Squeeze the glutes, then lower under control."],w:"Tuck your chin and keep ribs down. The bench should sit just under your shoulder blades."},
leg_curl:{s:["Set the pad just above your heels and the thigh pad snug.","Curl your heels toward your butt as far as they go.","Pause for a beat at the peak.","Let the weight back down slowly, resisting the whole way."],w:"The lowering half is where hamstrings grow. Don't let the stack slam back."},
standing_calf:{s:["Stand with the balls of your feet on a step or plate, heels hanging off.","Hold a dumbbell in each hand at your sides.","Rise as high onto your toes as you can.","Pause a second at the top, then sink into a full stretch."],w:"Bouncing at the bottom uses the tendon, not the muscle. Full stretch, full pause."},
seated_calf:{s:["Sit on a bench with the balls of your feet on a plate or step.","Rest a dumbbell on each knee.","Push up onto your toes as high as possible.","Lower to a deep stretch."],w:"Bent knees shift the work to the soleus, so expect to use less weight than standing."},
single_leg_calf:{s:["Stand on one foot with the ball of that foot on a step.","Hold something for balance, not for support.","Rise as high as you can onto the toe.","Lower into a full stretch below step level."],w:"Balance is the limiter, not strength. Hold the rack lightly with one finger."},
seated_db_press:{s:["Sit on a bench with the back support upright.","Bring the bells to shoulder height, palms facing forward.","Press straight overhead until your arms lock.","Lower to ear level."],w:"Keep your ribs down and don't arch off the bench. Wrists stack over elbows."},
standing_ohp:{s:["Stand with feet hip-width, bells at shoulder height.","Squeeze your glutes and brace your core.","Press overhead, moving your head slightly forward as the bells clear it.","Lower to shoulders under control."],w:"No leg drive. If you're dipping and bouncing, that's a push press."},
arnold_press:{s:["Start with bells at chest height, palms facing you.","As you press up, rotate your palms to face forward.","Lock out overhead.","Reverse the rotation on the way down."],w:"The rotation happens during the press, not before it. Go lighter than a normal press."},
push_press:{s:["Stand with bells at shoulder height.","Dip a few inches at the knees, torso staying vertical.","Explode up, using the leg drive to launch the bells overhead.","Lower back to shoulders."],w:"A short, sharp dip. Bending too deep turns it into a thruster."},
lateral_raise:{s:["Stand with a light dumbbell in each hand at your sides.","Lead with your elbows, raising your arms out to the sides.","Stop at shoulder height, no higher.","Lower slowly."],w:"Everyone goes too heavy here. If you're swinging, halve the weight."},
seated_lateral_raise:{s:["Sit upright on a bench, light bells at your sides.","Raise your arms out to shoulder height, leading with the elbows.","Pause at the top.","Lower under control."],w:"Sitting removes the leg swing, so you'll need less weight than standing. That's the point."},
ez_upright_row:{s:["Hold an EZ bar with hands about shoulder-width.","Pull it straight up the front of your body, elbows leading.","Stop when your hands reach chest height.","Lower under control."],w:"Stop at chest height. Pulling to the chin pinches the shoulder for a lot of people."},
rear_delt_fly:{s:["Hinge at the hips until your torso is near parallel to the floor.","Let light bells hang under your chest, palms facing each other.","Raise them out to the sides, thumbs down.","Squeeze the back of the shoulders, then lower."],w:"Very light weight. If your traps are doing it, you're using too much."},
face_pull:{s:["Set a cable at upper-chest height with a rope attachment.","Grip the rope with both hands, palms facing in, and step back.","Pull toward your forehead, splitting the rope, elbows high and wide.","Return under control."],w:"Elbows stay at or above shoulder height the whole rep. This is the posture fix."},
rear_delt_raise:{s:["Lie chest-down on a bench set to about 30°.","Let light bells hang straight down, palms facing each other.","Raise them out to the sides, thumbs pointed down.","Lower slowly."],w:"The bench stops you from cheating. Keep the weight light and the reps slow."},
ez_curl:{s:["Hold an EZ bar at the angled grips, arms hanging.","Keep elbows pinned at your sides.","Curl to shoulder height.","Lower all the way to straight arms."],w:"Elbows drifting forward turns this into a front raise. Pin them to your ribs."},
hammer_curl:{s:["Stand with a dumbbell in each hand, palms facing your thighs.","Keep that neutral grip the whole rep.","Curl to shoulder height.","Lower under control."],w:"No wrist rotation. The neutral grip is what hits the forearm and brachialis."},
cable_curl:{s:["Set a rope or bar at the lowest pulley.","Stand a step back, elbows at your sides.","Curl up, squeezing at the top.","Lower slowly, keeping tension the whole way."],w:"Cables keep tension at the bottom where dumbbells go slack. Don't let the stack rest."},
incline_curl:{s:["Set a bench to 45° and sit back against it.","Let the bells hang straight down behind your torso.","Curl up without moving your elbows forward.","Lower to a full stretch."],w:"That stretched starting position is the whole point. Don't shrug your shoulders forward."},
concentration_curl:{s:["Sit on a bench, feet wide.","Brace your working elbow against the inside of the same-side thigh.","Curl the bell to your shoulder.","Lower to a full stretch."],w:"The elbow never leaves the thigh. That's what makes it strict."},
ez_21s:{s:["Hold an EZ bar with a shoulder-width grip.","Do 7 reps from full stretch to halfway.","Do 7 reps from halfway to the top.","Do 7 full-range reps."],w:"Use about half your normal curl weight. Set 3 of 21 should be genuinely hard."},
cross_hammer_curl:{s:["Stand with a dumbbell in each hand, neutral grip.","Curl one bell across your body toward the opposite shoulder.","Squeeze at the top.","Lower and alternate."],w:"The elbow stays at your side. Only the forearm crosses the body."},
ez_skullcrusher:{s:["Lie on a flat bench holding an EZ bar over your chest.","Keeping upper arms still, bend at the elbows.","Lower the bar toward your forehead or just behind it.","Extend back up without moving the elbows."],w:"Upper arms stay locked in place. If they swing back, you're pressing."},
oh_tri_ext:{s:["Hold one dumbbell overhead with both hands cupping the top plate.","Keep elbows close to your ears.","Lower the bell behind your head.","Extend back overhead."],w:"Elbows flare out as you fatigue. Keep them narrow or the triceps stop working."},
bench_dip:{s:["Sit on the edge of a bench, hands gripping beside your hips.","Slide your butt off, legs out in front.","Lower until your upper arms are about parallel to the floor.","Press back up."],w:"Don't go deeper than parallel. Below that puts real strain on the shoulder."},
ez_oh_ext:{s:["Sit or stand holding an EZ bar overhead with a narrow grip.","Keep upper arms vertical and close to your head.","Lower the bar behind your head.","Extend back up."],w:"Upper arms stay still and pointed at the ceiling. Only the forearms move."},
tri_kickback:{s:["Hinge at the hips, torso near parallel to the floor.","Pin your upper arm against your side, elbow bent.","Extend the forearm straight back until the arm is locked.","Return under control."],w:"Light weight, full lockout. The squeeze at the end is the entire exercise."},
hanging_knee_raise:{s:["Hang from a bar, arms straight.","Without swinging, pull your knees up toward your chest.","Curl your pelvis up at the top.","Lower slowly under control."],w:"If you're swinging, you're using momentum. Pause at the bottom of each rep."},
hanging_leg_raise:{s:["Hang from a bar with straight arms.","Keep your legs nearly straight.","Raise them until they're at least parallel to the floor.","Lower slowly without swinging."],w:"Much harder than knee raises. Bend the knees slightly if your form breaks down."},
bicycle_crunch:{s:["Lie on your back, hands lightly behind your head, shoulders off the floor.","Bring one knee in and rotate the opposite elbow toward it.","Extend the other leg straight out just above the floor.","Switch sides in a smooth pedaling motion."],w:"Don't yank your neck. Rotate through the ribs, not the arms."},
reverse_crunch:{s:["Lie on your back, hands flat beside your hips.","Bring your knees over your hips.","Curl your pelvis up so your hips leave the floor.","Lower slowly."],w:"Small range. The rep is lifting your hips, not swinging your legs."},
decline_situp:{s:["Hook your feet into a decline bench.","Hold a dumbbell against your chest.","Sit up by rolling the spine, not folding at the hip.","Lower under control."],w:"Don't drop back fast. The lowering half is most of the work."},
flutter_kicks:{s:["Lie on your back, hands under your glutes for support.","Lift both heels a few inches off the floor.","Alternate small, quick kicks up and down.","Keep the lower back pressed to the floor."],w:"If your lower back arches, raise your legs higher until it doesn't."},
v_up:{s:["Lie flat, arms overhead, legs straight.","Simultaneously lift your torso and legs to meet in a V.","Reach for your toes.","Lower everything under control."],w:"Bend the knees if you can't keep your legs straight. Don't sling yourself up."},
toes_to_bar:{s:["Hang from a bar with straight arms.","Pull your shoulder blades down.","Raise straight legs all the way up to touch the bar.","Lower slowly under control."],w:"The hardest core move here. Drop to leg raises if you can't do it without swinging."},
cable_crunch:{s:["Kneel facing a high pulley with a rope, hands beside your head.","Keep hips fixed in place.","Crunch your ribs toward your pelvis, rounding the spine.","Return under control."],w:"Hips do not move. If you're hinging at the hip, you've turned it into a pulldown."},
weighted_leg_raise:{s:["Hang from a bar holding a light dumbbell between your feet.","Raise your legs to parallel or higher.","Pause at the top.","Lower slowly without swinging."],w:"Squeeze the bell hard the whole set so it can't slip."},
hanging_knee_twist:{s:["Hang from a bar, arms straight.","Pull your knees up toward your chest.","At the top, rotate both knees to one side.","Lower under control, alternating sides."],w:"Rotate from the waist, not by swinging your hips."},
oblique_knee_raise:{s:["Hang from a bar, arms straight.","Pull your knees up and toward one shoulder in one motion.","Squeeze the side of your waist at the top.","Lower slowly, then do the other side."],w:"Lead with the hip, not the knee. Keep the upper body still."},
plank:{s:["Forearms on the floor, elbows under your shoulders.","Body in one straight line from heels to head.","Squeeze glutes and brace your abs.","Hold, breathing normally."],w:"Hips sagging or piking up. Tuck your pelvis slightly and squeeze."},
side_plank:{s:["Lie on your side, elbow under your shoulder.","Stack your feet and lift your hips off the floor.","Make a straight line from ankle to head.","Hold, then switch sides."],w:"Don't let the top hip roll forward or the bottom hip sag."},
side_plank_reach:{s:["Set up in a side plank on your forearm.","Reach your top arm straight to the ceiling.","Thread it under your torso, rotating through the ribs.","Return to the ceiling. That's one rep."],w:"Hips stay lifted the whole time. Only the torso rotates."},
copenhagen:{s:["Lie on your side with your top leg resting on a bench at knee or ankle height.","Prop up on your forearm, elbow under the shoulder.","Lift your hips so your body makes a straight line.","Hold, then switch sides."],w:"Start with the knee on the bench, not the ankle. This one is brutally hard at full length."},
hollow_hold:{s:["Lie on your back, arms overhead.","Press your lower back flat into the floor.","Lift your shoulders and legs a few inches off the floor.","Hold that dish shape."],w:"If your lower back lifts off the floor, tuck your knees in until it doesn't."},
hollow_rock:{s:["Get into a hollow hold position.","Keep the shape rigid.","Rock back and forth from shoulders to hips.","Move from the whole body, not by flexing."],w:"If the shape breaks apart while rocking, go back to static holds."},
dead_bug:{s:["Lie on your back, arms straight up, knees over hips at 90°.","Press your lower back into the floor.","Lower one arm overhead and the opposite leg toward the floor.","Return and switch sides."],w:"The lower back must stay flat. The moment it lifts, shorten the range."},
weighted_dead_bug:{s:["Lie on your back holding one dumbbell straight up with both hands.","Knees over hips at 90°.","Keeping the bell steady overhead, extend one leg toward the floor.","Return and alternate."],w:"The bell should not drift. If it wobbles, the weight is too heavy."},
shoulder_taps:{s:["Get into a push-up position, feet wider than usual.","Keeping hips level, lift one hand and tap the opposite shoulder.","Place it back down.","Alternate."],w:"Hips must not rock side to side. Widen your feet if they do."},
plank_up_down:{s:["Start in a forearm plank.","Press up onto one hand, then the other, into a push-up position.","Lower back down to one forearm, then the other.","Alternate which arm leads."],w:"Keep the hips as still as possible. Wide feet make this much easier."},
ab_wheel:{s:["Kneel holding the wheel under your shoulders.","Brace hard and roll forward, keeping your back flat.","Go only as far as you can without your hips sagging.","Pull back using your abs, not your arms."],w:"Range is earned. Start short. A sagging lower back at full extension is how people get hurt."},
bird_dog:{s:["On hands and knees, hands under shoulders, knees under hips.","Extend one arm forward and the opposite leg back.","Hold for a beat, keeping hips square to the floor.","Return and switch sides."],w:"Don't let the hip of the extended leg open toward the ceiling."},
mountain_climber:{s:["Start in a push-up position, hands under shoulders.","Drive one knee toward your chest.","Switch legs quickly, keeping your hips low.","Keep a steady rhythm."],w:"Hips rising turns it into cardio for your shoulders. Keep the body flat."},
russian_twist:{s:["Sit with knees bent, heels light on the floor, torso leaned back about 45°.","Hold a dumbbell at your chest with both hands.","Rotate the bell to one hip, then the other.","Keep your chest up throughout."],w:"Rotate through the ribs, not by swinging your arms side to side."},
woodchop:{s:["Set a cable high with a single handle.","Stand side-on, feet planted wide.","Pull the handle down and across your body toward the opposite hip.","Return under control, then do the other side."],w:"Rotate through the torso with the arms mostly straight. The hips pivot, they don't twist."},
pallof_press:{s:["Set a cable at chest height, stand side-on and grip the handle with both hands at your sternum.","Step out to create tension.","Press your hands straight out in front of you.","Resist the pull toward the machine, then return."],w:"The point is to not rotate. If your torso turns toward the stack, lighten it."},
db_side_bend:{s:["Stand holding one dumbbell at your side, other hand behind your head.","Bend sideways toward the weighted side, letting the bell slide down your leg.","Stop at a comfortable stretch.","Pull straight back up using your side, then switch."],w:"Bend only side to side. Leaning forward or back takes the obliques out of it."},
suitcase_carry:{s:["Pick up one heavy dumbbell at your side, like a suitcase.","Stand tall, shoulders level.","Walk with controlled steps for the set time.","Switch hands and repeat."],w:"Do not lean away from the weight. Staying square is the entire exercise."},
farmer_carry:{s:["Pick up a heavy dumbbell in each hand.","Stand tall, chest up, shoulders back.","Walk with short, controlled steps for the set time.","Set them down under control."],w:"Grip usually fails first. Don't let your shoulders round forward as you tire."},
shoulder_circles:{s:["Stand tall with a light dumbbell in each hand, palms facing down.","Raise both arms straight out to the sides at shoulder height.","Draw slow circles forward for half the time, keeping the arms locked out at shoulder height.","Reverse and circle backward for the rest of the time."],w:"Go far lighter than feels right, 5-10 lb at most. If the arms drop below shoulder height the delts stop working and it becomes a rest."},
archer_pushup:{s:["Set up in a push-up position with hands much wider than shoulder-width.","Lower toward one hand, bending that elbow while the other arm stays straight and slides out to the side.","Press back up off the bent arm.","Alternate to the other side."],w:"The straight arm is a kickstand, not a second pressing arm. If it bends, widen your stance or stay higher."},
wide_pushup:{s:["Place your hands well outside shoulder-width, fingers pointing slightly out.","Keep a straight line from heels to head.","Lower your chest between your hands until you feel the stretch.","Press back up."],w:"Wide hands put the shoulder at a worse angle. Stop short of a full floor touch if the front of the shoulder pinches."},
spiderman_pushup:{s:["Start in a standard push-up position, hands under your shoulders.","As you lower, drive one knee out to the side toward the same-side elbow.","Press back up and return the leg.","Alternate legs each rep."],w:"The knee travels out to the side, not under your body. Hips stay low and square to the floor."},
twist_lunge:{s:["Hold one dumbbell with both hands, arms extended straight out at chest height.","Step forward and slightly across into a shallow lunge.","Rotate your torso toward the lead leg, keeping the arms extended and the weight level.","Untwist, push back to standing, and repeat to the other side."],w:"Rotate through the ribs, not the lower back. Hips turn with the lunge; the spine should not be doing the twisting on its own."},
thruster:{s:["Hold a dumbbell at each shoulder, feet shoulder-width.","Squat to parallel or below.","Drive up hard and let the momentum carry the bells overhead in one motion.","Lower them back to the shoulders as you descend into the next rep."],w:"It is one movement, not a squat then a press. If you pause at the top of the squat you have lost the point."},
bench_stepover:{s:["Stand side-on to a flat bench holding a dumbbell in each hand.","Step up onto the bench with the near foot, bring the other foot up.","Step down the far side, one foot then the other.","Come back the same way. One trip across and back is one rep."],w:"Place the whole foot on the bench. A heel hanging off is how you slip."},
burpee_over_bells:{s:["Lay two dumbbells side by side on the floor, a foot apart.","Do a burpee beside them: hands down, feet back, chest to floor, feet in, stand.","Hop or step sideways over the bells.","Burpee on the other side and come back."],w:"Look at the bells as you jump. Clipping one with a foot is the injury here, not the burpee."},
punch_out:{s:["Hold a light dumbbell (3 to 5 lb) in each hand at your chin, elbows in.","Feet staggered, knees soft, weight on the balls of your feet.","Throw straight punches, alternating hands, rotating the hips into each one.","Bring each hand straight back to the chin. Keep the pace up for the whole window."],w:"Light means light. Heavy bells here wreck the shoulder and slow you down until it stops being conditioning."},
jump_squat:{s:["Feet shoulder-width, arms at your sides.","Squat to about parallel, arms swinging back.","Jump as high as you can, arms driving up.","Land softly on the balls of your feet and sink straight into the next rep."],w:"Land quietly. A loud landing means stiff knees taking the shock."},
stair_intervals:{s:["Pick a level you can hold for 30 seconds at a hard climb.","Climb hard for 30 seconds without holding the rails.","Drop the level for 30 seconds of easy stepping.","Repeat until the time is up. Log the hard level."],w:"Hands off the rails except for balance. Leaning on them takes half the work out of it."},
alt_snatch:{s:["One dumbbell on the floor between your feet, feet shoulder-width.","Hinge down, grab it, and drive with the hips.","Pull the bell in a straight line up your body and punch it overhead in one motion.","Lower it to the floor and switch hands. Alternate every rep."],w:"The hips do the lifting. If the arm is pulling the bell up, go lighter."},
man_maker:{s:["Push-up position with a hand on each dumbbell.","Do a push-up, then row one bell, then the other.","Jump the feet in, stand up into a squat clean, and press both bells overhead.","Lower to the shoulders, put the bells down, and repeat."],w:"Each rep has five parts. Do them all, slowly if you have to. Rushing it turns into flailing."},
skater_hop:{s:["Stand on one leg, other leg trailing behind.","Bound sideways, landing on the other foot.","Let the trailing leg swing behind you as you absorb the landing.","Bound back the other way."],w:"Stick each landing before you push off again. A wobble on one foot is the whole exercise."},
squat_thrust:{s:["Stand, then crouch and put your hands on the floor.","Jump both feet back to a plank.","Jump them back in to the crouch.","Stand up. No push-up, no jump at the top."],w:"Keep the hips level in the plank. Sagging or piking at the bottom is a burpee done badly."},
battle_ropes:{s:["Hold the rope ends, feet wide, knees bent, back flat.","Whip both arms up and down as fast as you can for the window.","Keep the waves going all the way to the anchor.","Rest fully between rounds."],w:"Waves come from the arms and shoulders, with the legs braced. Standing tall and flopping the wrists does nothing."},
devil_press:{s:["Dumbbells on the floor a foot apart, hands on them.","Do a push-up between the bells, then jump the feet in.","Swing both bells between the legs and up overhead in one motion.","Lower them to the floor and repeat."],w:"Snatch the bells with the hips, not the arms. If you are curling them up, go lighter."},
hang_clean:{s:["Hold a dumbbell in each hand at your sides.","Hinge slightly so the bells hang at knee height.","Jump the bells up with the hips, shrug, and catch them at the shoulders with the elbows high.","Lower them back to the hang and repeat."],w:"Catch with the legs bent. Catching stiff-legged puts all of it into the lower back."},
db_bent_row:{s:["Hold a dumbbell in each hand, hinge at the hips until the torso is near flat.","Let the bells hang under your shoulders.","Row them to your hips, elbows tracking back.","Lower to a full stretch without losing the hinge."],w:"The back stays flat and the torso stays still. If you are heaving to lift the bells, they are too heavy."},
broad_jump:{s:["Feet shoulder-width, arms at your sides.","Sink into a quarter squat, swinging the arms back.","Jump forward as far as you can, arms driving forward.","Land soft on both feet and walk back. Each jump is one rep."],w:"Land with bent knees and the chest up. Landing stiff or falling forward means you jumped further than you can absorb."},
hand_release_pushup:{s:["Push-up position, hands under the shoulders.","Lower all the way until your chest touches the floor.","Lift both hands off the floor for a beat.","Put them down and press back up."],w:"Keep the body rigid as you press off the floor. If the hips come up first, the rep does not count."},
stair_intervals_long:{s:["Pick a level you can hold for a full minute at a hard climb.","Climb hard for one minute without holding the rails.","Drop the level for one easy minute.","Repeat until the time is up. Log the hard level."],w:"A minute is long. Start a level lower than the 30-second version and earn it back."},
turkish_getup:{s:["Lie on your back holding a dumbbell straight up over one shoulder, same-side knee bent.","Roll up onto the opposite elbow, then the hand.","Lift the hips, sweep the straight leg back under you to a kneeling position.","Stand up, eyes on the bell the whole way. Reverse every step to get back down."],w:"Learn it with no weight. Watch a video the first time; the sweep-through is the part everyone gets wrong."},
single_arm_press:{s:["Stand with one dumbbell at the shoulder, other hand on your hip or out for balance.","Brace the core so the torso does not lean away.","Press straight overhead until the arm locks.","Lower to the shoulder. Do all reps on one side, then switch."],w:"The torso wants to lean away from the bell. Fight it. Leaning is the obliques quitting."},
single_arm_cable_row:{s:["Set the pulley at chest height and take one handle.","Step back into a staggered stance, arm extended.","Row the handle to your ribs, rotating the torso slightly toward the working side.","Let it return to a full stretch. Do all reps on one side, then switch."],w:"Let the shoulder blade move. Pin it and you are just doing a bicep curl."},
cable_pull_through:{s:["Set the pulley low with a rope, face away from it, rope between your legs.","Walk forward until there is tension, feet shoulder-width.","Hinge at the hips, letting the rope pull your hands back between the legs.","Drive the hips forward to stand tall, squeezing the glutes."],w:"It is a hinge, not a squat. Knees stay softly bent and the shins stay vertical."},
dead_hang:{s:["Grab the pull-up bar, hands shoulder-width or a bit wider.","Hang with straight arms and let the shoulders rise toward your ears.","Relax everything below the grip. Breathe.","Hold for the time, then step down."],w:"Let the shoulders go. An active pull-down is a different exercise; this one is about letting the spine and lats stretch."},
deep_squat_hold:{s:["Feet a bit wider than shoulder-width, toes turned out slightly.","Sit all the way down, hips below the knees.","Push the knees out with the elbows and lift the chest.","Hold, breathing normally. Hold a light dumbbell in front if the heels lift."],w:"Heels stay on the floor. If they lift, the ankles are the problem and a dumbbell held out front fixes it."},
single_arm_floor_press:{s:["Lie on your back with a dumbbell in one hand, knees bent.","Start with the upper arm on the floor, elbow at about 45° from your ribs.","Press straight up until the arm locks.","Lower until the upper arm touches the floor again."],w:"The free hand goes on the floor or your stomach, not behind your head. The floor stops the elbow, so the bottom of each rep is a real pause."},
half_kneel_woodchop:{s:["Set the pulley high. Kneel on the inside knee, outside foot forward.","Take the handle with both hands over the shoulder nearest the stack.","Pull it down and across your body to the opposite hip, arms mostly straight.","Return under control. Do all reps, then switch sides."],w:"The hips stay square. Rotate the ribs, not the pelvis."},
cable_rotation:{s:["Set the pulley at chest height, stand side-on to it.","Take the handle with both hands, arms straight out in front.","Rotate away from the stack, turning the torso and pivoting the back foot.","Come back slowly. Do all reps, then switch sides."],w:"Arms stay straight and at chest height. Bending the elbows turns it into a pull."},
bear_crawl:{s:["Hands under shoulders, knees under hips, lift the knees an inch off the floor.","Move the opposite hand and foot forward together.","Keep the hips level and low, back flat.","Crawl forward for the time or distance, then back."],w:"Small steps. Long strides lift the hips and the whole point is keeping them down."},
overhead_carry:{s:["Press a dumbbell in each hand overhead, arms locked.","Pull the ribs down so the lower back does not arch.","Walk slowly and deliberately for the time.","Lower the bells to the shoulders, then the floor."],w:"Ribs down, glutes tight. An arched back overhead is the one place this can hurt you."},
goblet_cossack:{s:["Hold one dumbbell at your chest, feet very wide.","Sit down toward one side, that knee bending, the other leg straight with the toes up.","Go as low as you can with the heel down and the chest up.","Push back to the middle and go to the other side."],w:"The straight leg's heel stays down. If it lifts, narrow the stance."},
clean_and_press:{s:["Dumbbells at your sides, feet shoulder-width.","Hinge, then jump the bells up and catch them at the shoulders.","Press both overhead to lockout.","Lower to the shoulders, then to the hang, and repeat."],w:"Two moves with a pause between. Clean, settle, press. Bouncing the press off the clean is a push press."},
suitcase_deadlift:{s:["One dumbbell on the floor beside one foot, standing tall.","Hinge and bend the knees to grab it, back flat.","Stand up, driving through the floor, without leaning toward the bell.","Lower it back to the floor. Do all reps, then switch sides."],w:"Stay dead level. The bell wants to tip you sideways, and not tipping is the exercise."},
cable_antirotation_hold:{s:["Set the pulley at chest height, stand side-on to it.","Hold the handle with both hands and press it straight out from your chest.","Hold there. The stack will try to turn you toward it.","Hold for the time, then switch sides."],w:"Arms fully extended. If they drift back toward the chest, the load is too heavy."},
half_kneel_pulldown:{s:["Set the pulley high with a single handle. Kneel on the knee nearest the stack, other foot forward.","Take the handle with the hand on the kneeling side, arm extended overhead.","Pull the elbow down to your ribs, keeping the torso tall.","Return to a full stretch. Do all reps, then switch sides."],w:"Do not lean back. Kneeling takes away the cheat, so if you are leaning the weight is too heavy."},
wall_sit:{s:["Back flat against a wall, feet about two feet out.","Slide down until the thighs are parallel to the floor.","Knees over the ankles, hands off the thighs.","Hold for the time."],w:"Hands on the thighs is a rest. Arms crossed or at your sides."},
hip_9090:{s:["Sit on the floor, one leg bent 90° in front, the other bent 90° out to the side.","Sit tall over the front hip. Hold for the time.","Lean forward over the front shin to deepen it.","Switch sides by swinging both knees across to the other side."],w:"Both sit bones stay down. If one lifts, sit taller or put a hand behind you."},
cossack_squat:{s:["Feet very wide, toes pointing slightly out.","Sit toward one side, that knee bending, the other leg straight with the toes pointing up.","Go as low as you can with the heel down and the chest up.","Push back to the middle and go to the other side."],w:"This is the mobility version. Go slow and go for depth, not reps."},
deep_squat_pry:{s:["Sit into a deep squat, feet a bit wider than shoulder-width.","Put the elbows inside the knees, palms together.","Push the knees out with the elbows and rock gently side to side.","Keep the chest up and breathe."],w:"Rock, do not bounce. Slow pressure opens the hips; bouncing just tightens them."},
couch_stretch:{s:["Kneel facing away from a wall or bench, one shin up against it, that knee on the floor.","Step the other foot forward into a lunge.","Squeeze the glute on the back leg and stand the torso up tall.","Hold for the time, then switch."],w:"Squeeze the glute. Without it the stretch goes into the lower back instead of the hip flexor."},
thoracic_ext_bench:{s:["Kneel facing a flat bench, elbows on it, hands together as if praying.","Sit the hips back toward your heels.","Let the chest drop between your arms, head between the elbows.","Hold two breaths at the bottom, come up, repeat."],w:"Hands stay together and the elbows stay on the bench. Spreading the arms turns it into a shoulder stretch."},
band_pull_apart:{s:["Hold a light band with both hands, arms straight out in front at shoulder height.","Pull the hands apart until the band touches your chest.","Squeeze the shoulder blades together for a beat.","Return slowly."],w:"Arms stay straight and at shoulder height. Dropping them turns it into a row."},
wall_slide:{s:["Stand with your back, head and arms flat against a wall, elbows at 90°.","Slide the arms up the wall, keeping wrists and elbows touching it.","Go as high as you can without anything leaving the wall.","Slide back down."],w:"Ribs stay down. Arching the back to get the arms higher is not more range, it is cheating."},
incline_walk:{s:["Set the treadmill to a steep incline and a brisk walking pace.","Hands off the rails, arms swinging.","Walk for the time.","Log the incline as the level."],w:"Holding the rails makes it flat walking on a slope. Let go."},
pigeon:{s:["From hands and knees, bring one knee forward behind the same-side wrist, shin angled across.","Slide the other leg straight back.","Square the hips and fold forward over the front shin.","Hold for the time, then switch."],w:"If the front knee complains, bring the foot closer to the hip. The stretch belongs in the glute."},
worlds_greatest:{s:["Step into a long lunge, both hands on the floor inside the front foot.","Drop the inside elbow toward the floor.","Rotate that arm up toward the ceiling, following it with your eyes.","Bring the hand back down, straighten the front leg to stretch the hamstring, then switch sides."],w:"Move slowly through every position. It is five stretches in one rep and rushing skips four of them."},
cat_cow:{s:["Hands under shoulders, knees under hips.","Breathe out and round the whole spine toward the ceiling, head dropping.","Breathe in and arch, chest and tailbone lifting, head coming up.","Move slowly between the two."],w:"Move every vertebra, not just the lower back. The upper back is usually the stiff part."},
adductor_rockback:{s:["On hands and knees, stretch one leg straight out to the side, foot flat.","Keep the hips level.","Rock the hips back toward the heel of the kneeling leg.","Come forward again. Do all reps, then switch."],w:"The straight leg's foot stays flat on the floor. If it rolls, shorten the stance."},
scapular_pullup:{s:["Hang from the bar with straight arms.","Without bending the elbows, pull the shoulder blades down and together.","Your body rises an inch or two.","Let it back down to a full hang."],w:"Elbows stay locked. The moment they bend it is a pull-up and the shoulder blades stop doing the work."},
band_dislocate:{s:["Hold a light band wide in front of your thighs, arms straight.","Raise it over your head and behind you until it touches your back.","Keep the arms straight the whole way.","Bring it back over the top."],w:"Wider grip means easier. If the elbows bend, go wider."},
prone_ytw:{s:["Lie face down on a bench or the floor, arms hanging.","Raise the arms into a Y, thumbs up, squeeze, lower.","Raise them into a T, squeeze, lower.","Bend the elbows and raise them into a W, squeeze, lower. That is one rep."],w:"No weight or the lightest bells you can find. The shoulder blades do the lifting, not the arms."},
stair_easy:{s:["Set the stair machine to a level you can talk at.","Step for the time without holding the rails.","Stay at that level. This is a cool-down, not a workout.","Log the level."],w:"Easy means easy. If you are breathing hard, drop a level."},
frog_stretch:{s:["On hands and knees, walk the knees out wide, feet turned out.","Forearms on the floor.","Rock the hips back toward the heels until you feel the inner thighs.","Hold for the time, breathing."],w:"Keep the ankles in line with the knees, not tucked in. Tucking them takes the stretch out."},
jefferson_curl:{s:["Stand on a bench or step holding one light dumbbell in both hands.","Tuck the chin and roll down one vertebra at a time, letting the bell hang.","Go as far as you can, knees straight.","Roll back up from the bottom of the spine to the top."],w:"Light. 10 to 20 lb is plenty, and the slowness is the exercise."},
quadruped_t_rotation:{s:["On hands and knees, put one hand behind your head.","Rotate that elbow down toward the opposite wrist.","Rotate it up toward the ceiling, following it with your eyes.","Do all reps, then switch."],w:"Rotate from the upper back. Hips stay level and square to the floor."},
ankle_rock:{s:["Kneel with one foot forward, flat on the floor.","Drive that knee forward over the toes, heel staying down.","Go as far as you can, then back.","Do all reps, then switch."],w:"Heel stays down. The moment it lifts you have gone past your range."},
active_hang:{s:["Hang from the bar with straight arms.","Pull the shoulder blades down and away from your ears, and hold there.","Keep the ribs down and the body in a straight line.","Hold for the time."],w:"This is the dead hang's opposite. Shoulders stay packed down the whole time."},
backpack_thruster:{s:["Load a backpack with whatever is heavy and hug it to your chest.","Squat to parallel or below.","Drive up and press the pack overhead in one motion.","Lower it to the chest as you descend into the next rep."],w:"Hug it tight. A pack that swings pulls you forward."},
backpack_squat:{s:["Wear the loaded backpack or hug it to your chest.","Feet shoulder-width, sit down to parallel or below.","Keep the chest up and the heels down.","Drive back up."],w:"Chest up. The pack wants to fold you forward."},
backpack_row:{s:["Hold the loaded backpack by its top handle in one hand.","Hinge at the hips, other hand on a chair or bed.","Row the pack to your hip, elbow tracking back.","Lower to a full stretch. Do all reps, then switch."],w:"Keep the shoulders square. Rotating the torso to lift the pack is cheating."},
backpack_carry:{s:["Hold the loaded backpack by its handle at your side, or overhead with a locked arm.","Stand tall, shoulders level.","Walk for the time, switching hands halfway.","Set it down without rounding the back."],w:"Do not lean away from it. Staying level is the work."},
chair_stepup:{s:["Stand facing a sturdy chair or step.","Step up with one whole foot, driving through the heel.","Bring the other foot up, then step down the same way.","Alternate the lead leg each rep."],w:"Test the chair first. Hotel chairs are not all sturdy."},
burpee:{s:["Stand, crouch, hands on the floor.","Jump the feet back to a plank and lower the chest to the floor.","Press up, jump the feet back in.","Stand and jump, reaching overhead."],w:"Chest to the floor every rep. A half burpee is a squat thrust."},
pike_pushup:{s:["Push-up position, then walk the feet in and lift the hips high so the body makes an inverted V.","Bend the elbows and lower the head toward the floor between the hands.","Press back up.","Keep the hips high the whole time."],w:"The head goes down and forward, not straight down. Elbows track back, not out."},
scapular_pushup:{s:["Push-up position, arms locked straight.","Without bending the elbows, let the chest sink between the shoulder blades.","Push the floor away so the upper back rounds and the shoulder blades spread.","Repeat, small and slow."],w:"Elbows stay locked. It is a two-inch movement."},
childs_pose:{s:["Kneel with the big toes together and knees wide.","Sit the hips back to the heels and reach the arms forward on the floor.","Let the forehead rest on the floor.","Breathe into the back for the time."],w:"Hips toward the heels, even if they do not get there. Reaching further with the arms is not the stretch."},
standing_forward_fold:{s:["Stand with feet hip-width, knees soft.","Tuck the chin and roll down one vertebra at a time.","Let the arms and head hang. Hold, breathing.","Roll back up slowly from the bottom of the spine."],w:"Knees can bend. This is a spine stretch, not a hamstring test."},
stairwell_climb:{s:["Find the hotel stairwell.","Climb hard for a flight or two, then walk back down easy.","Repeat for the time.","Log the number of flights as the level."],w:"Walk the descent. Running down stairs is how you end the trip early."},
walk:{s:["Go outside.","Walk briskly for the time.","Arms swinging, head up.","Log the minutes."],w:"Brisk. If you can sing, speed up."}
};
